function validate([grid, moveCost]) {
  const m = grid.length;
  if (m < 2 || m > 50) return 'grid needs 2 to 50 rows.';
  const n = grid[0].length;
  if (n < 2 || n > 50) return 'Each row needs 2 to 50 columns.';
  if (grid.some(row => row.length !== n)) return 'All rows of grid must have the same length.';
  const seen = new Set(grid.flat());
  if (seen.size !== m * n || grid.flat().some(v => !Number.isInteger(v) || v < 0 || v >= m * n)) return 'grid must hold each number from 0 to m * n - 1 once.';
  if (moveCost.length !== m * n) return 'moveCost needs m * n rows.';
  if (moveCost.some(row => row.length !== n)) return 'Each moveCost row needs n entries.';
  if (moveCost.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > 100))) return 'Each move cost is between 1 and 100.';
  return null;
}

