function minPathCost(grid, moveCost) {
  const rows = grid.length;
  const cols = grid[0].length;
  let dp = grid[0].slice();

  for (let r = 1; r < rows; r++) {
    const next = new Array(cols).fill(Infinity);
    for (let c = 0; c < cols; c++) {
      for (let prev = 0; prev < cols; prev++) {
        const value = grid[r - 1][prev];
        const cost = dp[prev] + moveCost[value][c];
        if (cost < next[c]) {
          next[c] = cost;
        }
      }
      next[c] += grid[r][c];
    }
    dp = next;
  }
  return Math.min(...dp);
}

