function minPathCost(grid, moveCost) {
  let best = Infinity;
  const walk = (row, col, total) => {
    total += grid[row][col];
    if (row === grid.length - 1) { best = Math.min(best, total); return; }
    for (let j = 0; j < grid[0].length; j++) walk(row + 1, j, total + moveCost[grid[row][col]][j]);
  };
  for (let j = 0; j < grid[0].length; j++) walk(0, j, 0);
  return best;
}

