function generate(rand, size) {
  let m, n, top;
  if (size === 'large') {
    const shapes = [[40, 20], [7, 50], [50, 10], [10, 40], [50, 5]];
    [m, n] = shapes[Math.floor(rand() * shapes.length)];
    top = 100;
  } else {
    m = 2 + Math.floor(rand() * 3);
    n = 2 + Math.floor(rand() * 3);
    top = rand() < 0.5 ? 5 : 100;
  }
  const values = Array.from({ length: m * n }, (_, i) => i);
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  const grid = Array.from({ length: m }, (_, r) => values.slice(r * n, (r + 1) * n));
  const moveCost = Array.from({ length: m * n }, () => Array.from({ length: n }, () => 1 + Math.floor(rand() * top)));
  return [grid, moveCost];
}
